#!/bin/bash
# Run a speech script inside the NeMo container (GB10), with the HF cache, data and repo mounted, under the lock.
SP=$(cd $(dirname $0) && pwd)
exec flock /tmp/fastconformer-trt.lock docker run --rm --gpus all --ipc=host --ulimit memlock=-1 \
  -v $HOME/.cache/huggingface:/root/.cache/huggingface -v ${ASR_DATA_DIR:-$HOME/asr_data}:/data -v $SP:/w -w /w -e PYTHONPATH=/w \
  -e ASR_DATA=/data -e ASR_MODEL=${ASR_MODEL:-nvidia/parakeet-tdt-0.6b-v3} -e ASR_DECODING=${ASR_DECODING:-greedy_batch} -e GATE_POOL=${GATE_POOL:-drop} -e PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True -e POOL_RULE=${POOL_RULE:-pool2} -e LEAN_PREMASK_ONCE=${LEAN_PREMASK_ONCE:-0} -e LEAN_HALF=${LEAN_HALF:-0} -e LEAN_QUANT=${LEAN_QUANT:-fp8} -e LEAN_DWSHIFT=${LEAN_DWSHIFT:-0} -e LEAN_RELSHIFT=${LEAN_RELSHIFT:-0} -e LEAN_POOL43=${LEAN_POOL43:--1} -e FFN_PLUGIN_LIB=${FFN_PLUGIN_LIB:-} -e LEAN_HB=${LEAN_HB:-0} -e LEAN_CALIB=${LEAN_CALIB:-} -e LEAN_POSCACHE=${LEAN_POSCACHE:-0} -e FLEURS_SPLIT=${FLEURS_SPLIT:-test} -e LEAN_SUBMASK=${LEAN_SUBMASK:-0} -e LEAN_CKPT=${LEAN_CKPT:-} -e LEAN_QKV=${LEAN_QKV:-0} -e LEAN_QKV_PLUGIN=${LEAN_QKV_PLUGIN:-0} -e LEAN_ATTN_PLUGIN=${LEAN_ATTN_PLUGIN:-0} -e FFN_RESIDUAL=${FFN_RESIDUAL:-0} -e FFN_SPARSE=${FFN_SPARSE:-0} -e QKV_SPARSE=${QKV_SPARSE:-0} -e SP_DENSE=${SP_DENSE:-0} -e FFN_FP4=${FFN_FP4:-0} -e FFN_FP4_SKIP=${FFN_FP4_SKIP:-} -e SUB_PW3=${SUB_PW3:-0} -e FAST_JOINT_FP8=${FAST_JOINT_FP8:-0} -e PIPE_TRACE=${PIPE_TRACE:-} -e RELPOS_DK=${RELPOS_DK:-128} ${ASR_IMAGE:-fastconformer-trt:25.11} python "$@"
